<arrowlink COLOR="#954368" DESTINATION="ID_1985216414" ENDARROW="Default" ENDINCLINATION="1507;68;" ID="Arrow_ID_1698932113" STARTARROW="None" STARTINCLINATION="-35;216;"/>
