<linktarget COLOR="#f71732" DESTINATION="ID_118806151" ENDARROW="Default" ENDINCLINATION="5;-41;" ID="Arrow_ID_1345035443" SOURCE="ID_303221939" STARTARROW="None" STARTINCLINATION="-123;-2;"/>
<font NAME="SansSerif" SIZE="12"/>
