<linktarget COLOR="#b52e62" DESTINATION="ID_1565968263" ENDARROW="Default" ENDINCLINATION="-20;-92;" ID="Arrow_ID_43564391" SOURCE="ID_1120580246" STARTARROW="None" STARTINCLINATION="74;-2;"/>
