<linktarget COLOR="#544b67" DESTINATION="ID_1191577011" ENDARROW="Default" ENDINCLINATION="22;-64;" ID="Arrow_ID_370847933" SOURCE="ID_1402655083" STARTARROW="None" STARTINCLINATION="-378;15;"/>
