<linktarget COLOR="#daffc5" DESTINATION="ID_122410804" ENDARROW="Default" ENDINCLINATION="-352;-925;" ID="Arrow_ID_194808318" SOURCE="ID_804638831" STARTARROW="None" STARTINCLINATION="544;39;"/>
