<linktarget COLOR="#944347" DESTINATION="ID_1820151066" ENDARROW="Default" ENDINCLINATION="-878;49;" ID="Arrow_ID_1447249364" SOURCE="ID_1878650028" STARTARROW="None" STARTINCLINATION="767;30;"/>
