<linktarget COLOR="#8c303b" DESTINATION="ID_1536301470" ENDARROW="Default" ENDINCLINATION="-653;972;" ID="Arrow_ID_1675114658" SOURCE="ID_668512282" STARTARROW="None" STARTINCLINATION="373;-24;"/>
