<icon BUILTIN="yes"/>
<node COLOR="#435e98" CREATED="1734214271580" FOLDED="true" ID="ID_1045815708" MODIFIED="1734725343560" TEXT="Nochmal &#xfc;ber die Rolle der FeedManifold nachdenken">
<linktarget COLOR="#2e2c57" DESTINATION="ID_1045815708" ENDARROW="Default" ENDINCLINATION="-93;-205;" ID="Arrow_ID_639104343" SOURCE="ID_525858909" STARTARROW="None" STARTINCLINATION="-250;9;"/>
