<linktarget COLOR="#7f434f" DESTINATION="ID_1077913675" ENDARROW="Default" ENDINCLINATION="-259;8;" ID="Arrow_ID_1789073668" SOURCE="ID_1365275183" STARTARROW="None" STARTINCLINATION="165;-11;"/>
