<icon BUILTIN="button_cancel"/>
<node CREATED="1700361526878" ID="ID_981729861" MODIFIED="1700361562965" TEXT="damit implizierte Frage: ist Draw sinnvollerweise std::function ?"/>
<node CREATED="1700361585230" ID="ID_1897786487" MODIFIED="1700361617245" TEXT="wenn ja: dann w&#xe4;re der Ergebnistyp Draw&amp;">
<node CREATED="1700361662236" ID="ID_430183904" MODIFIED="1700361674294" TEXT="m&#xfc;&#xdf;te auf sich selber referenzieren"/>
<node CREATED="1700361695735" ID="ID_1277775461" MODIFIED="1700361713576" TEXT="sonst w&#xfc;rde ja der Builder-Ansatz nicht mehr funktionieren"/>
<node CREATED="1700361734947" ID="ID_1547996439" MODIFIED="1700361766613" TEXT="damit ist dann aber &#x3bb;-RES:Draw unm&#xf6;glich">
<icon BUILTIN="stop-sign"/>
<node CREATED="1700361779036" ID="ID_35323612" MODIFIED="1700361782723" TEXT="dangling reference"/>
</node>
</node>
<node CREATED="1700361800384" ID="ID_1496434440" MODIFIED="1700361807492" TEXT="alternativ: Ergebnistyp Spec">
<node CREATED="1700361809672" ID="ID_797207468" MODIFIED="1700361818203" TEXT="dann m&#xfc;&#xdf;ten wir den jedes Mal konstruieren"/>
</node>
<node CREATED="1700361859497" ID="ID_1388286109" MODIFIED="1700361872195" TEXT="oder : Ergebnistyp Limited">
<node CREATED="1700361873265" ID="ID_971481403" MODIFIED="1700361878704" TEXT="nicht mehr per Konversions-Operator"/>
<node CREATED="1700361879302" ID="ID_947380994" MODIFIED="1700361904631" TEXT="man m&#xfc;&#xdf;te dann jeweils einen Ausgangs-Adapter installieren"/>
</node>
<node CREATED="1700361955468" ID="ID_171432809" MODIFIED="1700361964999" TEXT="oder : Draw ist keine Fuktion">
<node CREATED="1700361966107" ID="ID_440284003" MODIFIED="1700361977187" TEXT="der operator() hat einen Seiteneffekt"/>
<node CREATED="1700361977817" ID="ID_527836444" MODIFIED="1700361991395" TEXT="anschlie&#xdf;end hold man sich das Ergebnis per Konversions-Operator"/>
</node>
