<node BACKGROUND_COLOR="#eee5c3" COLOR="#990000" CREATED="1699985086607" ID="ID_764096140" MODIFIED="1699989914820" STYLE="bubble">
<richcontent TYPE="NODE"><html>
  <head/>
  <body>
    <p>
      <u>Grundstruktur </u>
    </p>
    <p>
      
    </p>
    <p>
      <font face="Monospaced" size="2">digraph { </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;// Nodes </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N1[label=1, shape=doublecircle] </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N2[label=2] </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N3[label=3] </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N4[label=4] </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N5[label=5, shape=circle] </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N6[label=6] </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N7[label=7, shape=box, style=rounded] </font>
    </p>
    <p>
      
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;//Layers </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;{ /*0*/ rank=min&#160;&#160;N1 } </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;{ /*1*/ rank=same N2 N3 } </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;{ /*2*/ rank=same N4 N5 N6 } </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;{ /*3*/ rank=same N7 } </font>
    </p>
    <p>
      
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;// Topology </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N1 -&gt; {N2,N3} </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N2 -&gt; {N4,N6} </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N3 -&gt; {N4} </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N4 -&gt; {N7} </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N5 -&gt; {N7} </font>
    </p>
    <p>
      <font face="Monospaced" size="2">&#160;&#160;N6 -&gt; {N7} </font>
    </p>
    <p>
      <font face="Monospaced" size="2">} </font>
    </p>
  </body>
</html></richcontent>
