<icon BUILTIN="idea"/>
<node CREATED="1710634497736" ID="ID_1105327187" MODIFIED="1710634511410" TEXT="each plotting command generates a new canvas"/>
<node CREATED="1711673919442" ID="ID_1327600492" MODIFIED="1711673955214" TEXT="for fine control: need to give set size / set origin before each draw">
<richcontent TYPE="NOTE"><html>
  <head/>
  <body>
    <pre http-equiv="content-type" content="text/html; charset=utf-8">      set multiplot
      set size 0.4,0.4
      set origin 0.1,0.1
      plot sin(x)
      set size 0.2,0.2
      set origin 0.5,0.5
      plot cos(x)
      unset multiplot</pre>
  </body>
</html></richcontent>
