<linktarget COLOR="#804261" DESTINATION="ID_52631420" ENDARROW="Default" ENDINCLINATION="150;7;" ID="Arrow_ID_549406601" SOURCE="ID_1976063610" STARTARROW="None" STARTINCLINATION="350;33;"/>
